/* Spring 2027 review questions (added Nov 14, 2026). Same format as review.js; merged by BioLab.addReview.
   "verify" is read only by the test script. */
BioLab.addReview({
crosses:{
  apNote:'Released questions from College Board. Genetics questions use Punnett squares, probability rules and chi-square tests.',
  ap:[{title:'AP Biology past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'},
      {title:'AP Biology equations and formulas sheet',url:'https://apcentral.collegeboard.org/media/pdf/ap-biology-equations-and-formulas-sheet.pdf',note:'Chi-square table and probability rules.'}],
  questions:[
  {id:'dimples',kind:'real',lvl:'bio',
    q:'Your parents both have freckles, but you don’t. Freckles are dominant. How is that possible?',
    choices:['Both parents carry one hidden “no freckles” allele (Ff), and you got both hidden copies','Freckles skip generations on purpose','You must have a mutation','It is not possible'],correct:0,
    steps:['A dominant trait shows with one copy, so a parent with freckles can be FF or Ff.','If both are Ff, each child has a 1 in 4 chance of getting f from both: ff.','ff has no freckles. Many real traits involve more than one gene, but the idea is the same.'],
    lab:{set:{mode:'mono',p1m:'Pp',p2m:'Pp'},act:'breed100',look:'Count how many offspring show the recessive (white) trait.'}},
  {id:'ratio',kind:'test',lvl:'bio',
    q:'Pp × Pp. What fraction of the offspring are expected to be purple?',
    choices:['3/4','1/2','1/4','All of them'],correct:0,
    steps:['The Punnett square gives PP, Pp, Pp and pp.','PP and Pp are purple: 3 of 4.','So 3/4 purple and 1/4 white, a 3:1 ratio.'],
    lab:{set:{mode:'mono',p1m:'Pp',p2m:'Pp'},look:'Read <b>Expected ratio</b>.'}},
  {id:'test',kind:'test',lvl:'bio',
    q:'A purple plant (PP or Pp?) is crossed with a white pp plant. All 40 offspring are purple. What is the purple plant’s genotype, most likely?',
    choices:['PP','Pp','pp'],correct:0,
    steps:['A Pp parent would give about half white offspring.','40 purple and 0 white would be extremely unlikely from Pp (about 1 in a trillion).','So the purple parent is almost surely PP. This is called a testcross.'],
    lab:{set:{mode:'mono',p1m:'PP',p2m:'pp'},act:'breed20',look:'Compare with Pp × pp.'}},
  {id:'dihybrid',kind:'test',lvl:'honors',
    q:'YyRr × YyRr. What fraction of the offspring are yellow and wrinkled (Y_rr)?',
    choices:['3/16','9/16','1/16','1/4'],correct:0,
    steps:['Treat each gene separately: P(yellow) = 3/4, P(wrinkled) = 1/4.','Independent genes multiply: 3/4 × 1/4 = 3/16.','The full ratio is 9:3:3:1.'],
    lab:{set:{mode:'di',p1d:'YyRr',p2d:'YyRr'},act:'breed100',look:'Read <b>Expected ratio</b> and <b>Observed</b>.'}},
  {id:'colorblind',kind:'real',lvl:'honors',
    q:'Red-green color blindness is X-linked recessive. A woman who carries it (XᴮXᵇ) and a man with normal vision (XᴮY) have a son. What is the chance he is color-blind?',
    choices:['1/2','1/4','0','All sons'],correct:0,
    steps:['A son gets his Y from his father and one X from his mother.','The mother’s X is Xᵇ half the time.','So each son has a 1/2 chance. Daughters get Dad’s Xᴮ, so none would be color-blind. That is why about 8% of men but under 1% of women are.'],
    lab:{set:{mode:'xlinked',mom:'XRXr',dad:'XRY'},act:'breed100',look:'Compare white-eyed sons and daughters.'}},
  {id:'pink',kind:'test',lvl:'honors',
    q:'Two pink snapdragons (CᴿCᵂ) are crossed. What ratio of colors do you expect?',
    choices:['1 red : 2 pink : 1 white','3 red : 1 white','All pink','1 red : 1 white'],correct:0,
    steps:['With incomplete dominance the heterozygote shows an in-between color.','The square gives CᴿCᴿ, 2 CᴿCᵂ, CᵂCᵂ.','So 1 red : 2 pink : 1 white. Each genotype has its own look.'],
    lab:{set:{mode:'incomplete',p1i:'RW',p2i:'RW'},act:'breed100',look:'Read <b>Expected ratio</b>.'}},
  {id:'chisq',kind:'ap',lvl:'ap',
    q:'A Pp × Pp cross gives 70 purple and 30 white. Calculate χ² for the expected 3:1 ratio.',
    num:{ans:1.33,tol:.03},
    steps:['Expected: 75 purple, 25 white.','χ² = (70 − 75)²/75 + (30 − 25)²/25 = 0.333 + 1.00 = 1.33.','With df = 1 the critical value is 3.84. 1.33 is smaller, so the data fit 3:1.']},
  {id:'mapunits',kind:'ap',lvl:'ap',
    q:'In a testcross, 180 of 1000 offspring are recombinant. How far apart are the two genes?',
    num:{ans:18,tol:.1,unit:'map units'},
    steps:['Recombination frequency = 180 ÷ 1000 = 0.18.','1% recombinants = 1 map unit.','So the genes are 18 map units apart on the same chromosome.'],
    lab:{set:{mode:'linked',rf:18},act:'breed100',look:'Read <b>Recombinant offspring</b>.'}}
  ]},
bloodtype:{
  apNote:'Released questions from College Board. Blood-type questions combine codominance, multiple alleles and antigen–antibody reactions.',
  ap:[{title:'AP Biology past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'clump',kind:'test',lvl:'bio',
    q:'A blood sample clumps with anti-A serum but not with anti-B. What is the ABO type?',
    choices:['Type A','Type B','Type AB','Type O'],correct:0,
    steps:['Anti-A clumps red blood cells that carry the A antigen.','No clumping with anti-B means no B antigen.','A antigen only: type A.'],
    lab:{set:{view:'lab',patient:1},act:'a',look:'Add anti-A and anti-B and watch for clumping.'}},
  {id:'donor',kind:'real',lvl:'bio',
    q:'In an emergency with no time to test, why do hospitals give type O-negative blood?',
    choices:['O− red cells carry no A, B or Rh antigens, so almost no one’s antibodies attack them','O− blood clots fastest','O− is the most common type','It has extra antibodies'],correct:0,
    steps:['Your antibodies attack red cells with antigens you don’t have.','O− cells have none of the three main antigens.','So they are safe for nearly everyone. That makes O− donors especially valuable at blood drives.']},
  {id:'ab',kind:'test',lvl:'bio',
    q:'A sample clumps with both anti-A and anti-B. What type is it?',
    choices:['AB','O','A','B'],correct:0,
    steps:['Clumping with anti-A means A antigen; with anti-B means B antigen.','Both antigens: type AB.','The Iᴬ and Iᴮ alleles are codominant: both show.']},
  {id:'parents',kind:'test',lvl:'honors',
    q:'A type A parent (IᴬI) and a type B parent (IᴮI) have a child. Which types are possible?',
    choices:['A, B, AB or O','Only AB','Only A or B','Only O'],correct:0,
    steps:['Parent 1 passes Iᴬ or i; parent 2 passes Iᴮ or i.','Combinations: IᴬIᴮ (AB), IᴬI (A), IᴮI (B), ii (O).','Each has a 1/4 chance.'],
    lab:{set:{view:'family'},look:'Test the family and work out each person’s genotype.'}},
  {id:'rh',kind:'test',lvl:'honors',
    q:'Blood clumps with anti-Rh. What does that mean?',
    choices:['The person is Rh positive','The person is Rh negative','The person is type O','Nothing'],correct:0,
    steps:['Anti-Rh clumps cells that carry the Rh (D) antigen.','Clumping means the antigen is present: Rh+.','About 85% of people are Rh+.'],
    lab:{set:{view:'lab',patient:2},act:'rh',look:'Read <b>Anti-Rh well</b>.'}},
  {id:'hw',kind:'ap',lvl:'ap',
    q:'In a sample, 49% of people are type O (ii). Assuming Hardy–Weinberg, what is the frequency of the i allele?',
    num:{ans:.7,tol:.01},
    steps:['Type O is ii, so q² = 0.49.','q = √0.49 = 0.70.','That is close to many real populations, where i is the most common ABO allele.'],
    lab:{set:{view:'pop'},act:'pop',look:'Read <b>Type O in sample</b> and <b>Estimated i allele</b>.'}}
  ]},
pedigree:{
  apNote:'Released questions from College Board. Pedigree questions ask you to decide the pattern of inheritance from a family tree.',
  ap:[{title:'AP Biology past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'symbols',kind:'test',lvl:'bio',
    q:'In a pedigree, what does a filled-in circle mean?',
    choices:['A female who shows the trait','A male who shows the trait','A female carrier','A male carrier'],correct:0,
    steps:['Circles are females; squares are males.','Filled in means the person has the trait.','A half-filled or dotted symbol often marks a carrier.']},
  {id:'skip',kind:'test',lvl:'bio',
    q:'Two unaffected parents have an affected child. What does that tell you?',
    choices:['The trait is recessive; both parents are carriers','The trait is dominant','The trait is Y-linked','It must be a new mutation'],correct:0,
    steps:['A dominant trait shows in anyone who has the allele.','Unaffected parents with an affected child means the allele was hidden in both of them.','So the trait is recessive and both parents are heterozygous carriers.'],
    lab:{set:{person:'II-1'},look:'Inspect the people in each generation.'}},
  {id:'cf',kind:'real',lvl:'honors',
    q:'Cystic fibrosis is autosomal recessive. Both parents are carriers. What is the chance their next baby has CF?',
    choices:['1/4','1/2','0','3/4'],correct:0,
    steps:['Each carrier parent is Cc.','Cc × Cc gives CC, Cc, Cc, cc: 1/4 cc.','The chance is 1/4 for every pregnancy, no matter what happened before. Genetic counselors help families understand this.']},
  {id:'dominant',kind:'test',lvl:'honors',
    q:'A trait appears in every generation, and every affected child has an affected parent. Which pattern fits best?',
    choices:['Autosomal dominant','Autosomal recessive','X-linked recessive','The trait is not genetic'],correct:0,
    steps:['Dominant traits rarely skip generations: you need only one copy to show it.','Recessive traits often skip, appearing in children of unaffected carriers.','So every generation affected points to dominant.']},
  {id:'xlinked',kind:'ap',lvl:'ap',
    q:'In a pedigree, nearly all affected people are males, and affected males’ daughters have affected sons. Which pattern fits?',
    choices:['X-linked recessive','Autosomal dominant','Y-linked','Autosomal recessive'],correct:0,
    steps:['Males have one X, so one recessive allele shows.','An affected father passes his X to every daughter, making them carriers.','Carrier daughters pass it to half their sons: the classic hemophilia pattern.'],
    lab:{act:'newfam',look:'Try several families and decide the pattern for each.'}}
  ]},
karyotype:{
  apNote:'Released questions from College Board. Karyotype questions link chromosome number to nondisjunction in meiosis.',
  ap:[{title:'AP Biology past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'count',kind:'test',lvl:'bio',
    q:'How many chromosomes are in a typical human body cell?',
    choices:['46 (23 pairs)','23','48','92'],correct:0,
    steps:['Humans have 22 pairs of autosomes plus one pair of sex chromosomes.','That is 23 pairs, or 46 chromosomes.','Egg and sperm cells have 23, one of each pair.'],
    lab:{act:'auto',look:'Count the chromosomes in the arranged karyogram.'}},
  {id:'sex',kind:'test',lvl:'bio',
    q:'A karyogram shows XY at the sex-chromosome spot. What does that mean?',
    choices:['The person is chromosomally male','Female','A mistake','Down syndrome'],correct:0,
    steps:['XX is typical of females and XY of males.','The Y chromosome carries the SRY gene that starts male development.','The Y is much smaller than the X.']},
  {id:'down',kind:'test',lvl:'honors',
    q:'A karyogram has three copies of chromosome 21. What condition is this, and how many chromosomes in total?',
    choices:['Down syndrome (trisomy 21), 47 chromosomes','Turner syndrome, 45','Down syndrome, 45','Normal, 46'],correct:0,
    steps:['Trisomy means one extra copy of a chromosome.','46 + 1 = 47.','Trisomy 21 is Down syndrome, the most common trisomy in live births (about 1 in 700).'],
    lab:{act:'newcase',look:'Arrange each new patient and check for missing or extra chromosomes.'}},
  {id:'nondis',kind:'test',lvl:'honors',
    q:'How does a person end up with an extra chromosome?',
    choices:['Nondisjunction: a pair fails to separate in meiosis, so one egg or sperm gets two copies','The chromosome copies itself after birth','Too much DNA in the diet','Mitosis makes an extra copy in every cell'],correct:0,
    steps:['In meiosis, each pair should split so each gamete gets one copy.','If a pair sticks together, one gamete gets two copies and another gets none.','A gamete with two copies plus a normal gamete gives a zygote with three.']},
  {id:'turner',kind:'ap',lvl:'ap',
    q:'A karyogram shows 45 chromosomes with a single X and no Y. What is it?',
    choices:['Turner syndrome (45,X)','Klinefelter syndrome (47,XXY)','Down syndrome','A typical male'],correct:0,
    steps:['Only one sex chromosome, an X.','45,X is Turner syndrome, which affects females.','It can come from nondisjunction in either parent; Klinefelter is the extra-X condition in males.']}
  ]},
replication:{
  apNote:'Released questions from College Board. Replication questions ask what each enzyme does and why one strand is made in pieces.',
  ap:[{title:'AP Biology past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'why',kind:'test',lvl:'bio',
    q:'Why must DNA be copied before a cell divides?',
    choices:['Each new cell needs a complete set of instructions','To make the cell bigger','To make proteins','It is not copied'],correct:0,
    steps:['Each daughter cell needs all the genes to work.','So the cell copies its entire DNA first.','Your body copies about 6 billion base pairs every time one of your cells divides.']},
  {id:'helicase',kind:'test',lvl:'bio',
    q:'What does helicase do?',
    choices:['Unzips the two strands at the fork','Joins the pieces of new DNA','Adds new nucleotides','Checks for errors'],correct:0,
    steps:['The two strands are held together by base pairs.','Helicase breaks those bonds so each strand can be read.','Without it, copying cannot start.'],
    lab:{set:{helicase:false},look:'Read <b>Fork speed</b>.'}},
  {id:'pairs',kind:'test',lvl:'bio',
    q:'One strand reads 5′–ATGC–3′. What does the new strand made against it read?',
    choices:['3′–TACG–5′','5′–ATGC–3′','3′–UACG–5′','5′–GCAT–3′'],correct:0,
    steps:['A pairs with T and G pairs with C.','So ATGC is matched by TACG.','The new strand runs the opposite direction (antiparallel).']},
  {id:'okazaki',kind:'test',lvl:'honors',
    q:'Why is the lagging strand made in short pieces?',
    choices:['DNA polymerase can only add to the 3′ end, so on that strand it must start over and over as the fork opens','The lagging strand is damaged','Helicase cuts it','It is made faster that way'],correct:0,
    steps:['DNA polymerase builds new DNA only 5′ → 3′.','On one template, that direction runs away from the fork.','So polymerase works in short stretches (Okazaki fragments) that ligase joins.'],
    lab:{look:'Watch the top strand build in pieces. Read <b>Okazaki fragments started</b>.'}},
  {id:'proof',kind:'real',lvl:'honors',
    q:'Without proofreading, DNA polymerase makes about 1 mistake per 100 000 bases. With proofreading and repair, about 1 per billion. Why does that matter?',
    choices:['Fewer mistakes means fewer mutations that could cause cancer or genetic disease','It makes copying faster','It changes the genetic code','It does not matter'],correct:0,
    steps:['Each mistake left behind is a mutation.','Without proofreading, a copy of your genome would carry tens of thousands of new mistakes.','Some inherited cancers come from broken repair genes.'],
    lab:{set:{proof:false},look:'Read <b>Expected errors per genome copy</b>.'}},
  {id:'mstahl',kind:'ap',lvl:'ap',
    q:'Meselson and Stahl grew E. coli in ¹⁵N, then moved them to ¹⁴N. After one generation they saw one band at hybrid density. What did that prove?',
    choices:['Replication is not conservative: each new DNA has one old strand and one new','Replication is conservative','DNA is made of protein','Nothing'],correct:0,
    steps:['Conservative replication would give one heavy and one light band.','One hybrid band rules that out.','After a second generation, a hybrid and a light band appeared, which ruled out dispersive and fit semiconservative.'],
    lab:{set:{mode:'ms'},look:'Read the heavy, hybrid and light percentages generation by generation.'}}
  ]},
expression:{
  apNote:'Released questions from College Board. Expression questions use the codon table and the effects of mutations on proteins.',
  ap:[{title:'AP Biology past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'flow',kind:'test',lvl:'bio',
    q:'What is the order of steps from gene to protein?',
    choices:['DNA → mRNA (transcription) → protein (translation)','Protein → mRNA → DNA','DNA → protein → mRNA','mRNA → DNA → protein'],correct:0,
    steps:['Transcription copies the gene into mRNA.','The mRNA travels to a ribosome.','Translation reads it three bases at a time to build the protein.'],
    lab:{act:'replay',look:'Watch transcription, then translation.'}},
  {id:'codon',kind:'test',lvl:'bio',
    q:'How many bases code for one amino acid?',
    choices:['3 (one codon)','1','2','4'],correct:0,
    steps:['mRNA is read in groups of three bases, called codons.','There are 64 codons and 20 amino acids, so most amino acids have more than one codon.','Three codons mean “stop.”']},
  {id:'vaccine',kind:'real',lvl:'bio',
    q:'mRNA vaccines give your cells mRNA for a virus’s spike protein. What do your cells do with it?',
    choices:['Ribosomes translate it into spike protein, which trains your immune system','The mRNA changes your DNA','The mRNA becomes a virus','Nothing'],correct:0,
    steps:['mRNA is the instructions ribosomes read; it never enters the nucleus or changes DNA.','Your cells make some harmless spike protein and display it.','Your immune system learns to recognize it. The 2023 Nobel Prize honored the work behind this.'],
    lab:{act:'replay',look:'Watch the ribosome read the mRNA.'}},
  {id:'frameshift',kind:'test',lvl:'honors',
    q:'Why does deleting one base usually damage a protein far more than substituting one base?',
    choices:['It shifts the reading frame, so every codon after it changes','It removes the whole gene','It always makes a stop codon','It does not'],correct:0,
    steps:['Codons are read in groups of three from a fixed start.','Removing one base shifts every later group.','Most amino acids after the deletion change, and a stop codon often appears early.'],
    lab:{set:{gene:'demo',pos:5},act:'del',look:'Read <b>Amino acids changed or lost</b>.'}},
  {id:'sickle',kind:'test',lvl:'honors',
    q:'In sickle-cell disease, GAG becomes GTG in the β-globin gene. What kind of mutation is it?',
    choices:['A missense substitution: one amino acid changes (Glu → Val)','A silent mutation','A frameshift','A nonsense mutation'],correct:0,
    steps:['One base changes, so it is a substitution.','GAG codes for glutamic acid; GTG for valine.','That single change makes hemoglobin clump at low oxygen, bending red cells into sickles.'],
    lab:{set:{gene:'hbb',pos:20,base:'T'},act:'sub',look:'Read <b>Mutation type</b>.'}},
  {id:'intron',kind:'ap',lvl:'ap',
    q:'What happens to introns before a eukaryotic mRNA leaves the nucleus?',
    choices:['They are spliced out, and the exons are joined','They are translated first','They are kept and translated','They become the 5′ cap'],correct:0,
    steps:['Introns are stretches inside the gene that don’t code for the protein.','Spliceosomes cut them out and join the exons.','The mature mRNA also gets a 5′ cap and a poly-A tail. Alternative splicing lets one gene make several proteins.'],
    lab:{set:{introns:true},act:'replay',look:'Read <b>RNA processing</b>.'}}
  ]},
lacoperon:{
  apNote:'Released questions from College Board. Operon questions ask how repressors and activators respond to the cell’s environment.',
  ap:[{title:'AP Biology past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'whyoff',kind:'test',lvl:'bio',
    q:'Why does E. coli keep its lactose genes off when there is no lactose?',
    choices:['Making enzymes it doesn’t need wastes energy','Lactose is poisonous','The genes are broken','It can’t make them'],correct:0,
    steps:['Proteins cost a lot of energy and materials to make.','With no lactose, the enzymes would have nothing to do.','So the repressor sits on the operator and blocks transcription.'],
    lab:{set:{lac:false,glc:false},look:'Read <b>Lac genes</b> and <b>β-galactosidase</b>.'}},
  {id:'on',kind:'test',lvl:'bio',
    q:'Lactose appears and there is no glucose. What happens?',
    choices:['Lactose binds the repressor, it lets go, and the genes turn on','The repressor binds tighter','Nothing','The cell dies'],correct:0,
    steps:['A form of lactose fits onto the repressor and changes its shape.','The repressor falls off the operator.','RNA polymerase can now transcribe the genes, and β-galactosidase rises.'],
    lab:{set:{lac:true,glc:false},look:'Read <b>β-galactosidase</b> over time.'}},
  {id:'lactose',kind:'real',lvl:'honors',
    q:'People who are lactose intolerant stop making lactase as adults. E. coli makes β-galactosidase only when lactose is around. What do the two have in common?',
    choices:['Both control when a lactose-digesting enzyme gene is turned on','Both are caused by bacteria','Both make lactose','Nothing'],correct:0,
    steps:['Lactase (in people) and β-galactosidase (in bacteria) both split lactose.','Each organism controls when its gene is on.','In most mammals the lactase gene turns down after weaning; some human groups evolved to keep it on.']},
  {id:'glucose',kind:'test',lvl:'honors',
    q:'Both glucose and lactose are present. Why is the operon only a little on?',
    choices:['With glucose around, cAMP is low, so CAP can’t boost transcription','The repressor is still bound','Glucose destroys lactose','The cell prefers lactose'],correct:0,
    steps:['Lactose removes the repressor.','But CAP needs cAMP to help RNA polymerase bind well, and cAMP is low when glucose is present.','The cell uses glucose first, its easiest fuel.'],
    lab:{set:{lac:true,glc:true},look:'Read <b>Lac genes</b>.'}},
  {id:'lacI',kind:'ap',lvl:'ap',
    q:'A lacI⁻ mutant makes no working repressor. What happens with no lactose (and no glucose)?',
    choices:['The genes are on all the time','The genes are off','Only some genes are on'],correct:0,
    steps:['lacI codes for the repressor.','No repressor means nothing blocks the operator.','The operon is always on: “constitutive” expression.'],
    lab:{set:{lacI:true,lac:false,glc:false},look:'Read <b>Lac genes</b>.'}}
  ]},
virus:{
  apNote:'Released questions from College Board. Virus questions compare lytic and lysogenic cycles and retroviruses.',
  ap:[{title:'AP Biology past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'alive',kind:'test',lvl:'bio',
    q:'Why can’t a virus reproduce on its own?',
    choices:['It has no ribosomes or metabolism, so it must use a host cell’s machinery','It is too small to see','It has no DNA or RNA','It reproduces by dividing'],correct:0,
    steps:['A virus is genes in a protein coat.','It has none of the machinery to make proteins or energy.','It injects its genes into a cell, and the cell builds new viruses.'],
    lab:{set:{type:'lytic'},look:'Watch the phage take over the bacteria.'}},
  {id:'lytic',kind:'test',lvl:'bio',
    q:'In the lytic cycle, what happens to the host cell?',
    choices:['It fills with new viruses and bursts','It survives and divides normally','It becomes a virus','It stores the virus forever'],correct:0,
    steps:['The virus takes over and makes many copies.','The cell breaks open (lyses) and releases them.','Each new virus can infect another cell, so the culture clears.'],
    lab:{set:{type:'lytic'},look:'Read <b>Culture cloudiness</b> over time.'}},
  {id:'lyso',kind:'test',lvl:'honors',
    q:'A temperate phage enters the lysogenic cycle. What happens to its DNA?',
    choices:['It joins the host chromosome and is copied every time the cell divides','It is destroyed','It bursts the cell right away','It leaves the cell'],correct:0,
    steps:['The phage DNA inserts into the bacterial chromosome.','It rides along silently as the bacterium divides.','Stress like UV light can switch it to the lytic cycle.'],
    lab:{set:{type:'temperate'},act:'uv',look:'Read <b>Lysogens</b> before and after the UV.'}},
  {id:'titer',kind:'test',lvl:'honors',
    q:'You plate 0.1 mL of a 10⁻⁶ dilution and count 45 plaques. What is the phage titer of the original?',
    num:{ans:4.5e8,tol:.1e8,unit:'phage per mL'},
    steps:['45 plaques came from 0.1 mL, so 450 per mL of the dilution.','Undo the dilution: 450 × 10⁶.','= 4.5 × 10⁸ phage per mL.'],
    lab:{set:{type:'lytic',dil:'6'},act:'plate',look:'Read <b>Plaques on last plate</b> and <b>Titer from that plate</b>.'}},
  {id:'hiv',kind:'real',lvl:'ap',
    q:'Why is HIV treated with three drugs at once instead of one?',
    choices:['A virus resistant to one drug is very unlikely to also resist two others, so resistance can’t take over','Three drugs are cheaper','One drug is too strong','It is not'],correct:0,
    steps:['HIV copies itself with many mistakes, so resistant mutants appear often.','With one drug, those mutants survive and take over.','Needing three lucky mutations at once makes resistance rare. Combination therapy turned HIV into a manageable condition.'],
    lab:{set:{type:'hiv',drug:'combo'},look:'Compare <b>Drug-resistant virus</b> with one drug and with the combo.'}}
  ]},
beaks:{
  apNote:'Released questions from College Board. Natural selection questions ask how variation, inheritance and differential survival change a population.',
  ap:[{title:'AP Biology past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'antibiotic',kind:'real',lvl:'bio',
    q:'Doctors tell you to finish all your antibiotics even when you feel better. How does natural selection explain why?',
    choices:['Stopping early leaves the toughest bacteria alive to multiply, so the population becomes more resistant','Antibiotics stop working after a few days','Bacteria learn to resist','It doesn’t matter'],correct:0,
    steps:['Bacteria vary: a few are harder to kill.','The weak ones die first; if you stop early, the tough survivors reproduce.','Each round selects for resistance, the same way drought selected for strong beaks.']},
  {id:'drought',kind:'test',lvl:'bio',
    q:'A drought leaves only large, hard seeds. Which birds become more common?',
    choices:['Birds with big, strong beaks','Birds with thin beaks','All birds equally','No birds survive'],correct:0,
    steps:['Big beaks crack hard seeds; thin beaks can’t.','More big-beaked birds survive and breed.','Their offspring inherit big beaks, so the population shifts. Peter and Rosemary Grant measured exactly this in Galápagos finches in 1977.'],
    lab:{set:{food:'drought'},look:'Watch the beak percentages change over the rounds.'}},
  {id:'individual',kind:'test',lvl:'bio',
    q:'Which statement about natural selection is true?',
    choices:['Populations change over generations; individuals don’t evolve','Each bird changes its beak to fit the food','Animals evolve because they need to','Selection creates new traits on demand'],correct:0,
    steps:['Each bird is born with its beak and keeps it.','Birds whose beaks fit the food survive and pass them on.','Over generations the population’s mix of beaks changes. That is evolution.']},
  {id:'variety',kind:'test',lvl:'honors',
    q:'Why must a population have variation for natural selection to happen?',
    choices:['Selection can only favor traits that are already present','Variation makes birds stronger','It doesn’t need variation','Variation causes mutation'],correct:0,
    steps:['Selection sorts existing differences: some survive better than others.','If every bird were identical, all would do equally well or badly.','New variation comes from mutation and recombination.'],
    lab:{set:{food:'nuts',mut:false},look:'If binder clips have died out, can they come back with mutation off?'}},
  {id:'fitness',kind:'ap',lvl:'ap',
    q:'In one round, 80% of clothespin birds survive and 40% of spoon birds survive. What is the relative fitness of spoons, with clothespins = 1?',
    num:{ans:.5,tol:.01},
    steps:['Relative fitness = survival of the type ÷ survival of the best type.','= 0.40 ÷ 0.80.','= 0.50.']}
  ]},
cladogram:{
  apNote:'Released questions from College Board. Phylogeny questions use shared derived characters to read and build trees.',
  ap:[{title:'AP Biology past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'derived',kind:'test',lvl:'bio',
    q:'Which trait would group a lizard, a bird and a mouse together but leave out a frog?',
    choices:['An amniotic egg (an egg with protective membranes)','A backbone','Four limbs','Hair'],correct:0,
    steps:['A useful trait is one some members share and others lack.','Frogs, lizards, birds and mice all have backbones and four limbs.','Only reptiles, birds and mammals have the amniotic egg, so it marks their branch.'],
    lab:{set:{set:'vert'},act:'next',look:'Place the traits one at a time and watch the branches form.'}},
  {id:'closest',kind:'test',lvl:'bio',
    q:'On a cladogram, how do you tell which two organisms are most closely related?',
    choices:['They share the most recent common ancestor (the nearest branch point)','They sit next to each other at the tips','They look the most alike','They are the same size'],correct:0,
    steps:['Each branch point stands for a common ancestor.','The pair whose branches join most recently shares the most recent ancestor.','Neighbors at the tips can still be distant if their branches meet low on the tree.']},
  {id:'birds',kind:'real',lvl:'honors',
    q:'Cladograms put birds closer to crocodiles than crocodiles are to lizards. What evidence supports that?',
    choices:['Shared derived traits like a gizzard, a four-chambered heart and certain skull openings, plus DNA','Birds and crocodiles look alike','They both live near water','Birds evolved from mammals'],correct:0,
    steps:['Birds and crocodiles share traits that lizards lack.','DNA comparisons agree.','Birds are living dinosaurs, part of the archosaur branch with crocodiles.']},
  {id:'plants',kind:'test',lvl:'honors',
    q:'Mosses, ferns, pine trees and flowering plants. Which trait separates ferns from mosses?',
    choices:['Vascular tissue (tubes that carry water)','Seeds','Flowers','Chlorophyll'],correct:0,
    steps:['All land plants have chlorophyll.','Ferns, pines and flowering plants have vascular tissue; mosses don’t, which keeps them short.','Seeds then separate pines and flowering plants from ferns.'],
    lab:{set:{set:'plant'},act:'next',look:'Build the land-plant cladogram trait by trait.'}},
  {id:'ladder',kind:'ap',lvl:'ap',
    q:'A student says, “Humans evolved from chimpanzees.” What does a cladogram show instead?',
    choices:['Humans and chimps share a common ancestor; both lineages kept evolving','Chimps are ancestors of humans','Humans are more evolved than chimps','They are unrelated'],correct:0,
    steps:['Living species sit at the tips of a tree, not along a ladder.','Humans and chimpanzees branch from an ancestor that lived about 6 to 7 million years ago.','Chimps have been evolving for exactly as long as we have.']}
  ]},
hominids:{
  apNote:'Released questions from College Board. Human evolution questions use fossil evidence and the branching pattern of evolution.',
  ap:[{title:'AP Biology past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'lucy',kind:'test',lvl:'bio',
    q:'Lucy (Australopithecus afarensis) walked upright but had a brain about the size of a chimpanzee’s. What does that tell us?',
    choices:['Upright walking evolved before big brains','Big brains evolved first','Lucy was a chimpanzee','Walking upright makes brains bigger right away'],correct:0,
    steps:['Lucy lived about 3.2 million years ago.','Her hips, knees and foramen magnum show upright walking; her braincase held about 450 cc.','Brains near our size (about 1350 cc) came much later.'],
    lab:{set:{species:'afarensis',scene:'brain'},look:'Compare Lucy’s brain size with yours.'}},
  {id:'together',kind:'test',lvl:'bio',
    q:'Did hominid species live one at a time, each turning into the next?',
    choices:['No: several species often lived at the same time','Yes, in a straight line','Only humans ever existed','Yes, but only in Europe'],correct:0,
    steps:['Fossils show overlap: Paranthropus lived alongside early Homo, and Neanderthals alongside Homo sapiens.','Human evolution is a branching bush, not a ladder.','Most branches died out; ours is the one left.'],
    lab:{set:{scene:'time'},look:'Look for species whose time ranges overlap.'}},
  {id:'foramen',kind:'test',lvl:'honors',
    q:'Why does the position of the foramen magnum (the hole where the spinal cord enters) tell you about walking?',
    choices:['Under the skull means the head balanced on an upright spine','Toward the back means upright','It shows brain size','It shows diet'],correct:0,
    steps:['In apes that walk on all fours, the hole is toward the back.','In upright walkers, it moves forward, under the skull.','So a fossil skull alone can show whether its owner walked on two legs.'],
    lab:{set:{scene:'fm'},look:'Compare the foramen magnum across species.'}},
  {id:'neander',kind:'real',lvl:'honors',
    q:'Many people today carry 1–2% Neanderthal DNA. What does that show?',
    choices:['Early Homo sapiens and Neanderthals met and had children together','Neanderthals evolved into modern humans','Modern humans are Neanderthals','It is contamination'],correct:0,
    steps:['Genomes from Neanderthal bones (Svante Pääbo’s work, 2022 Nobel Prize) can be compared with ours.','People with ancestry outside Africa carry small Neanderthal segments.','So the two groups interbred about 50 000 years ago before Neanderthals died out.']},
  {id:'eq',kind:'ap',lvl:'ap',
    q:'Why do scientists compare brain size to body size (EQ) instead of brain size alone?',
    choices:['Bigger bodies need bigger brains just to run them, so raw size misleads','Brain size is hard to measure','EQ is the same for every species','Body size doesn’t matter'],correct:0,
    steps:['An elephant’s brain is far bigger than ours.','Much of any brain controls the body, so large animals need large brains.','EQ asks how much brain a species has compared with what its body size predicts.'],
    lab:{set:{scene:'eq'},look:'Read <b>Encephalization quotient (EQ)</b> for each species.'}}
  ]},
dissection:{
  apNote:'Released questions from College Board. Organ system questions link structure to function.',
  ap:[{title:'AP Biology past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'diaphragm',kind:'test',lvl:'bio',
    q:'Which muscle separates the chest cavity from the abdominal cavity and helps you breathe?',
    choices:['The diaphragm','The heart','The liver','The stomach'],correct:0,
    steps:['The diaphragm is a dome of muscle under the lungs.','When it contracts and flattens, the chest gets bigger and air rushes in.','Hiccups are sudden spasms of the diaphragm.'],
    lab:{set:{mode:'pig',step:'thorax',part:'diaphragm'},look:'Find the diaphragm between the chest and abdomen.'}},
  {id:'liver',kind:'test',lvl:'bio',
    q:'What is the largest organ inside the abdomen?',
    choices:['The liver','The stomach','The small intestine','The kidney'],correct:0,
    steps:['The liver fills much of the upper abdomen.','It makes bile, stores sugar as glycogen and breaks down toxins.','The gallbladder underneath stores the bile.'],
    lab:{set:{mode:'pig',step:'five',part:'liver'},look:'Find the liver.'}},
  {id:'intestine',kind:'test',lvl:'honors',
    q:'Why is the small intestine so long and folded?',
    choices:['It gives a huge surface area for absorbing nutrients','To store waste','To make bile','To pump blood'],correct:0,
    steps:['Nutrients pass into the blood through the intestine’s lining.','More length and folds (plus villi) mean more surface.','A human small intestine is about 6 m long with a surface area of about 30 m².'],
    lab:{set:{mode:'pig',step:'intest',part:'smint'},look:'Find the small intestine.'}},
  {id:'ventricle',kind:'test',lvl:'honors',
    q:'Why is the left ventricle’s wall thicker than the right’s?',
    choices:['It pumps blood to the whole body, which takes more force than pumping to the nearby lungs','It holds more blood','It is a valve','It doesn’t'],correct:0,
    steps:['The right ventricle pushes blood a short way to the lungs.','The left ventricle pushes blood to every part of the body.','More work, more muscle: a structure–function match.'],
    lab:{set:{mode:'pig',step:'heart',part:'lv'},look:'Compare the left and right ventricle walls.'}},
  {id:'tracheae',kind:'ap',lvl:'ap',
    q:'A grasshopper has no lungs. How does oxygen reach its cells?',
    choices:['Air enters spiracles and travels through branching tracheae straight to the cells','Through its blood, like ours','Through its gizzard','It doesn’t need oxygen'],correct:0,
    steps:['Spiracles are small openings along the body.','They lead into air tubes that branch to every tissue.','This works only over short distances, one reason insects stay small today.'],
    lab:{set:{mode:'hopper',hstep:'hext',hpart:'spiracle'},look:'Find the spiracles.'}}
  ]},
homeostasis:{
  apNote:'Released questions from College Board. Homeostasis questions describe negative feedback loops and what happens when they fail.',
  ap:[{title:'AP Biology past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-biology/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'meal',kind:'test',lvl:'bio',
    q:'After lunch your blood sugar rises. What brings it back down?',
    choices:['Insulin from the pancreas tells cells to take in glucose','Glucagon','Sweating','Breathing faster'],correct:0,
    steps:['High blood sugar is sensed by the pancreas.','It releases insulin, and muscle, fat and liver cells take in glucose.','Blood sugar falls back toward normal: a negative feedback loop.'],
    lab:{set:{mode:'glucose',carbs:75},act:'meal',look:'Watch glucose rise, then insulin bring it down.'}},
  {id:'cold',kind:'real',lvl:'bio',
    q:'Waiting for the bus on a 10 °F morning, you start shivering. Why?',
    choices:['Shivering muscles make heat to keep your core near 37 °C','Your body is broken','You are getting a fever','Shivering cools you'],correct:0,
    steps:['Your brain senses your body cooling.','It triggers shivering (quick muscle contractions make heat) and narrows skin blood vessels to keep heat in.','When you warm up, it stops: negative feedback.'],
    lab:{set:{mode:'temp',ta:-10},look:'Read <b>Shivering</b> and <b>Core temperature</b>.'}},
  {id:'negative',kind:'test',lvl:'honors',
    q:'What makes a feedback loop “negative”?',
    choices:['The response reverses the change, pulling the value back to the set point','It is harmful','It makes the change bigger','It works only in illness'],correct:0,
    steps:['A change is sensed (for example, body temperature rises).','The response opposes it (sweating cools you).','That keeps conditions steady. Positive feedback, like labor contractions, pushes a change further.']},
  {id:'glucagon',kind:'test',lvl:'honors',
    q:'During a long practice without a snack, what keeps your blood sugar from crashing?',
    choices:['Glucagon tells the liver to release stored glucose','Insulin rises','Your muscles make sugar','Sweat'],correct:0,
    steps:['As blood sugar falls, the pancreas releases glucagon.','The liver breaks down glycogen into glucose and releases it.','Liver glycogen runs low after a couple of hours of hard exercise, which is why athletes eat carbs.'],
    lab:{set:{mode:'glucose'},act:'exercise',look:'Read <b>Glucagon</b> and <b>Liver glycogen</b>.'}},
  {id:'type1',kind:'ap',lvl:'ap',
    q:'In type 1 diabetes the immune system destroys insulin-making beta cells. Why does blood sugar stay high?',
    choices:['Without insulin, cells don’t take up glucose from the blood','Glucagon stops working','The person eats too much sugar','The liver stops storing glucose only'],correct:0,
    steps:['Insulin is the signal for cells to take in glucose.','No insulin, no signal: glucose builds up in the blood.','People with type 1 inject insulin, which replaces the missing part of the loop.'],
    lab:{set:{mode:'glucose',t1:true},look:'Read <b>Blood glucose</b>, then try <b>Inject insulin</b>.'}}
  ]},
climate:{
  apNote:'Released questions from College Board. APES climate questions link greenhouse gases, warming and solutions.',
  ap:[{title:'AP Environmental Science past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-environmental-science/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'greenhouse',kind:'test',lvl:'bio',
    q:'How does CO₂ warm the planet?',
    choices:['It absorbs heat (infrared) given off by Earth’s surface and sends some back down','It blocks sunlight','It makes the sun hotter','It thins the ozone layer'],correct:0,
    steps:['Sunlight warms the ground, which gives off infrared heat.','CO₂ and other greenhouse gases absorb some of that heat and re-emit it in all directions, including down.','More CO₂ traps more heat, like a thicker blanket.'],
    lab:{set:{path:'bau'},look:'Read <b>CO₂ in the air</b> and <b>Warming since 1850</b>.'}},
  {id:'bau',kind:'test',lvl:'bio',
    q:'If emissions keep growing (business as usual), about how much warming by 2100?',
    choices:['About 3 °C or more, more than twice today’s','About the same as today','Cooler than today','About 10 °C'],correct:0,
    steps:['Earth has warmed about 1.3 °C since 1850.','Rising emissions keep piling CO₂ into the air.','Models give about 3 °C or more by 2100 on that path.'],
    lab:{set:{path:'bau'},look:'Read <b>Warming since 1850</b> in 2100.'}},
  {id:'wedges',kind:'real',lvl:'bio',
    q:'Which of these is one stabilization “wedge” you could be part of?',
    choices:['Efficient cars and driving less','Cutting down forests','Burning more coal','Leaving lights on'],correct:0,
    steps:['A wedge is one action that grows to cut about 1 billion tons of carbon a year by mid-century.','Vehicles are a big share of US emissions, so efficient cars, EVs, carpooling and transit help.','No single wedge is enough; it takes many together.'],
    lab:{set:{path:'bau',pick:'cars'},act:'toggle',look:'Add wedges and watch emissions bend.'}},
  {id:'flat',kind:'test',lvl:'honors',
    q:'Emissions are held flat at today’s level. Why does CO₂ in the air keep rising?',
    choices:['We still add more CO₂ each year than oceans and plants remove','Flat emissions stop the rise immediately','CO₂ makes more CO₂','It doesn’t'],correct:0,
    steps:['Think of a bathtub: the faucet is emissions, the drain is natural uptake.','Today the faucet runs about twice as fast as the drain.','Holding the faucet steady still fills the tub, just more slowly. Only net zero stops the rise.'],
    lab:{set:{path:'flat'},look:'Read <b>CO₂ in the air</b> over time.'}},
  {id:'methane',kind:'test',lvl:'honors',
    q:'Why do cuts in methane slow warming quickly?',
    choices:['Methane traps far more heat per molecule than CO₂ but breaks down in about 10 years','Methane is not a greenhouse gas','It lasts thousands of years','It cools the planet'],correct:0,
    steps:['Over 20 years, a ton of methane traps about 80 times as much heat as a ton of CO₂.','It breaks down in the air in about a decade.','So cutting leaks from gas wells, landfills and farms pays off fast.'],
    lab:{set:{path:'bau',ch4:'low'},look:'Compare warming with methane cut, today’s and doubled.'}},
  {id:'acid',kind:'ap',lvl:'ap',
    q:'Ocean pH has fallen from about 8.2 to 8.05. Why does that matter for shellfish and corals?',
    choices:['More dissolved CO₂ makes the water more acidic, leaving less carbonate to build shells','Higher pH dissolves shells','pH doesn’t affect shells','The water is getting warmer only'],correct:0,
    steps:['CO₂ dissolves in seawater and forms carbonic acid.','The extra H⁺ ties up carbonate ions that animals need for calcium carbonate shells.','A 0.15 drop in pH is about 40% more H⁺. Oyster hatcheries in the Pacific Northwest already adjust their water.'],
    lab:{set:{path:'bau'},look:'Read <b>Ocean surface pH</b>.'}}
  ]},
energycalc:{
  apNote:'Released questions from College Board. APES energy questions use kWh, efficiency and unit conversions.',
  ap:[{title:'AP Environmental Science past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-environmental-science/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'hot',kind:'test',lvl:'bio',
    q:'An incandescent bulb feels hot. Where does most of its electricity go?',
    choices:['Into heat; only about 2% becomes light','Into light','Into sound','It is stored in the bulb'],correct:0,
    steps:['An incandescent bulb heats a wire until it glows.','Most of the energy comes out as heat (infrared).','An LED turns far more of its electricity into light, so it runs cool.'],
    lab:{set:{bulb:'incandescent'},look:'Read <b>Energy that becomes light</b> and the thermometer.'}},
  {id:'kwh',kind:'test',lvl:'bio',
    q:'A 9 W LED is on 5 hours a day for a year. How many kWh does it use?',
    num:{ans:16.4,tol:.1,unit:'kWh'},
    steps:['Energy = power × time = 9 W × 5 h × 365 days.','= 16 425 Wh.','= 16.4 kWh. The 60 W incandescent giving the same light uses 110 kWh.'],
    lab:{set:{bulb:'led',hours:5},look:'Read <b>Energy per year</b>.'}},
  {id:'cost',kind:'real',lvl:'honors',
    q:'Your family replaces a 60 W incandescent with a 9 W LED, on 5 hours a day, at 14¢/kWh. About how much do you save in a year?',
    num:{ans:13,tol:.3,unit:'$'},
    steps:['Saved power = 60 − 9 = 51 W.','51 W × 5 h × 365 = 93.1 kWh per year.','93.1 × $0.14 ≈ $13 per bulb per year. Swap 20 bulbs and that is about $260.']},
  {id:'co2',kind:'test',lvl:'honors',
    q:'A bulb uses 110 kWh a year on a grid that emits 0.55 kg CO₂ per kWh. How much CO₂ per year?',
    num:{ans:60.5,tol:.5,unit:'kg'},
    steps:['CO₂ = energy × emissions rate.','= 110 × 0.55.','= 60.5 kg of CO₂ per year.']},
  {id:'chain',kind:'ap',lvl:'ap',
    q:'A gas plant is 40% efficient, transmission loses 6%, and an LED makes light from 35% of its electricity. What fraction of the fuel’s energy becomes light?',
    num:{ans:13.2,tol:.3,unit:'%'},
    steps:['Multiply the efficiencies along the chain.','0.40 × 0.94 × 0.35 = 0.132.','About 13%. Every step loses energy as heat (second law of thermodynamics).'],
    lab:{set:{bulb:'led',plantEff:40,lineLoss:6},look:'Read <b>Fuel → light efficiency</b>.'}}
  ]},
gridmix:{
  apNote:'Released questions from College Board. APES energy questions compare sources, efficiency and the grid’s daily demand curve.',
  ap:[{title:'AP Environmental Science past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-environmental-science/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'night',kind:'test',lvl:'bio',
    q:'A city gets lots of power from solar farms. What has to supply the power after sunset?',
    choices:['Other sources (wind, gas, hydro, nuclear) or batteries charged during the day','The solar panels at a lower setting','Nothing; cities need no power at night','The moon'],correct:0,
    steps:['Solar makes power only while the sun is up.','Demand peaks in the early evening, just as solar fades.','Grids balance this with other plants, hydro and, more and more, big batteries.'],
    lab:{set:{solar:3000,coal:0,gas:0,wind:0,hydro:0},look:'Watch what happens to <b>Power short</b> at night.'}},
  {id:'coalgas',kind:'test',lvl:'bio',
    q:'Replacing coal plants with natural gas plants of the same size usually…',
    choices:['Cuts CO₂, because gas releases about half the CO₂ per kWh','Raises CO₂','Has no effect','Makes the grid 100% clean'],correct:0,
    steps:['Burning coal releases about 1 kg of CO₂ per kWh of electricity.','Gas plants release about 0.4–0.5 kg.','Still not zero, and methane leaks from gas wells and pipes cut into the benefit.'],
    lab:{set:{coal:0,gas:1600},look:'Read <b>CO₂ right now</b> and compare with the starting mix.'}},
  {id:'colorado',kind:'real',lvl:'bio',
    q:'Colorado has been replacing coal plants with wind farms on the eastern plains. What is the main trade-off?',
    choices:['Wind makes no CO₂ but varies with the weather, so the grid needs backup or storage','Wind makes more CO₂','Wind works only at night','There is no trade-off'],correct:0,
    steps:['Wind turbines burn no fuel, so they emit no CO₂ while running.','But the wind doesn’t blow on demand.','Grids pair wind with other sources, long transmission lines and batteries.'],
    lab:{set:{wind:2000,coal:0},look:'Turn on <b>Calm day</b> and see what fills the gap.'}},
  {id:'battery',kind:'test',lvl:'honors',
    q:'What do grid batteries do?',
    choices:['Store extra power when supply is high and release it when demand is high','Make new energy','Burn fuel','Work only in winter'],correct:0,
    steps:['Batteries don’t generate energy; they move it in time.','They charge from midday solar and discharge in the evening peak.','A 4-hour battery rated 1000 MW stores 4000 MWh.'],
    lab:{set:{solar:2500,wind:600,coal:400,gas:1200,battery:1000},look:'Read <b>Battery output</b> and <b>Battery charge</b> through the day.'}},
  {id:'mwh',kind:'test',lvl:'honors',
    q:'A 200 MW wind farm runs at an average of 40% of its rating for a full day. How much energy does it make?',
    num:{ans:1920,tol:5,unit:'MWh'},
    steps:['Average output = 0.40 × 200 MW = 80 MW.','Energy = 80 MW × 24 h.','= 1920 MWh, enough for about 64 000 homes for a day.']},
  {id:'heat',kind:'ap',lvl:'ap',
    q:'A gas plant is 50% efficient and delivers 500 MW of electricity. How much waste heat does it release?',
    num:{ans:500,tol:1,unit:'MW'},
    steps:['Fuel heat in = 500 ÷ 0.50 = 1000 MW.','Waste heat = 1000 − 500 = 500 MW.','That heat goes into cooling towers or a river, which is why plants need so much water.'],
    lab:{set:{gas:500,coal:0},look:'Read <b>Fuel heat burned</b>.'}}
  ]},
smog:{
  apNote:'Released questions from College Board. Air pollution questions separate primary and secondary pollutants and explain inversions.',
  ap:[{title:'AP Environmental Science past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-environmental-science/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'brown',kind:'real',lvl:'bio',
    q:'On some winter mornings a brown cloud sits over Denver. What traps it?',
    choices:['A thermal inversion: warm air above cold air near the ground acts like a lid','Fog from the mountains','Wind pushes pollution in','Snow releases it'],correct:0,
    steps:['Normally air cools with height, so warm polluted air rises and mixes away.','On calm winter nights, cold air pools in the valley under a warmer layer.','Pollution can’t rise through the lid and builds up until wind or sun breaks it.'],
    lab:{set:{season:'winter',wind:1.5,inv:true},look:'Read <b>Air Quality Index</b> with and without the inversion.'}},
  {id:'ozone',kind:'test',lvl:'bio',
    q:'Why does ground-level ozone peak in the afternoon, hours after rush hour?',
    choices:['Sunlight drives reactions between NOx and VOCs from the morning traffic','Ozone comes straight out of tailpipes','Ozone falls from the ozone layer','Afternoon traffic is worse'],correct:0,
    steps:['Cars emit NO, NO₂ and VOCs in the morning.','Sunlight powers reactions that turn them into ozone.','It takes hours of strong sun, so ozone peaks midday to afternoon in summer.'],
    lab:{set:{season:'summer'},look:'Watch ozone through the day.'}},
  {id:'wind',kind:'test',lvl:'bio',
    q:'A strong wind picks up on a hazy day. What happens to the AQI?',
    choices:['It improves (drops), because the wind mixes and carries pollution away','It worsens','No change'],correct:0,
    steps:['Wind spreads pollutants through a bigger volume of air.','Lower concentration means a lower AQI.','Calm, sunny, hot days are the worst for ozone alerts.'],
    lab:{set:{season:'winter',wind:8},look:'Read <b>Air Quality Index</b>.'}},
  {id:'secondary',kind:'test',lvl:'honors',
    q:'Which is a secondary pollutant?',
    choices:['Ground-level ozone','Carbon monoxide','Nitric oxide from exhaust','Soot'],correct:0,
    steps:['Primary pollutants come straight out of a source.','Secondary pollutants form in the air from primary ones.','Ozone forms from NOx and VOCs in sunlight, so it is secondary.']},
  {id:'voc',kind:'ap',lvl:'ap',
    q:'In summer, gasoline sold along the Front Range is blended to evaporate less. Why?',
    choices:['It cuts VOC emissions, one of the two ingredients of ozone','It saves money only','It lowers CO₂','It reduces particles'],correct:0,
    steps:['Gasoline vapor is a VOC, and gas evaporates faster in summer heat.','Ozone needs NOx and VOCs plus sunlight.','The Front Range doesn’t meet the federal ozone standard, so it targets VOCs in summer.'],
    lab:{set:{season:'summer',voc:30},look:'Compare the ozone peak at 100% and 30% VOCs.'}}
  ]},
acidrain:{
  apNote:'Released questions from College Board. Acid deposition questions use the pH scale, sources of SO₂ and NOx, and buffering.',
  ap:[{title:'AP Environmental Science past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-environmental-science/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'source',kind:'test',lvl:'bio',
    q:'What causes acid rain?',
    choices:['Sulfur dioxide and nitrogen oxides from burning fuels form acids in clouds','Carbon dioxide only','Salt from the ocean','Lightning only'],correct:0,
    steps:['Coal plants release SO₂; cars and plants release NOx.','In clouds they react with water to form sulfuric and nitric acids.','Rain carries the acid to lakes, forests and buildings.'],
    lab:{set:{coal:100,scrub:false},look:'Read <b>Rain pH</b>.'}},
  {id:'scrubber',kind:'test',lvl:'bio',
    q:'A coal plant installs scrubbers. What happens to the nearby lake over the next decade?',
    choices:['Its pH rises slowly and fish can return','Nothing changes','It gets more acidic','It dries up'],correct:0,
    steps:['Scrubbers spray limestone slurry that captures SO₂.','Less acid reaches the lake.','Lakes and soils recover slowly. US SO₂ emissions have fallen over 90% since 1990, and many Northeast lakes are recovering.'],
    lab:{set:{scrub:true},look:'Watch <b>Granite Lake pH</b> and <b>Trout</b> over time.'}},
  {id:'tenx',kind:'test',lvl:'honors',
    q:'Clean rain is about pH 5.6. Acid rain at pH 4.6 is how many times as acidic?',
    choices:['10 times','1 time','2 times','100 times'],correct:0,
    steps:['Each pH unit is a 10-times change in H⁺.','5.6 − 4.6 = 1 unit.','So 10 times the H⁺.']},
  {id:'granite',kind:'test',lvl:'honors',
    q:'Two lakes get the same acid rain. One sits on granite, one on limestone. Which acidifies?',
    choices:['The granite lake','The limestone lake','Both equally'],correct:0,
    steps:['Limestone (CaCO₃) neutralizes acid: CaCO₃ + 2H⁺ → Ca²⁺ + CO₂ + H₂O.','Granite has almost no buffering.','So the granite lake’s pH drops and trout die off, while the limestone lake stays near neutral.'],
    lab:{look:'Compare <b>Granite Lake pH</b> and <b>Limestone Lake pH</b>.'}},
  {id:'liming',kind:'ap',lvl:'ap',
    q:'Adding limestone to an acid lake raises its pH. Why is it not a permanent fix if the acid rain continues?',
    choices:['The limestone gets used up as it neutralizes the new acid','Limestone dissolves acid forever','It lowers the pH','Fish eat the limestone'],correct:0,
    steps:['Each mole of CaCO₃ neutralizes 2 moles of H⁺ and is gone.','If acid keeps arriving, the buffer runs out.','Fixing the source (scrubbers, low-sulfur coal, cleaner cars) is what lasts.'],
    lab:{act:'lime',look:'Add limestone and watch the pH jump, then fall back.'}}
  ]},
eutrophication:{
  apNote:'Released questions from College Board. Eutrophication questions trace nutrients to algae to oxygen loss.',
  ap:[{title:'AP Environmental Science past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-environmental-science/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'lawn',kind:'real',lvl:'bio',
    q:'Fertilizer from lawns washes into a pond and the pond turns green. What happens weeks later?',
    choices:['The algae die, bacteria decompose them, and the bacteria use up the oxygen, so fish can die','The pond gets more oxygen forever','Nothing','The fish grow bigger'],correct:0,
    steps:['Nitrogen and phosphorus feed an algae bloom.','When the algae die, decomposers break them down and use oxygen.','Bottom water can run out of oxygen. Following the label and not fertilizing before rain helps.'],
    lab:{set:{runoff:100},look:'Watch <b>Algae</b>, then <b>Bottom oxygen</b> and <b>Fish</b> over time.'}},
  {id:'warm',kind:'test',lvl:'bio',
    q:'Why does warm water hold less oxygen?',
    choices:['Gases dissolve less in warmer water','Warm water has fewer fish','Algae use it','It doesn’t'],correct:0,
    steps:['Gas molecules escape more easily from warmer water.','At 30 °C, water holds about 7.6 mg/L of O₂ at saturation; at 10 °C, about 11.3.','Warm summer water plus a bloom is the worst case for fish.'],
    lab:{set:{temp:30},look:'Read <b>Surface oxygen</b> at 15 °C and 30 °C.'}},
  {id:'buffer',kind:'test',lvl:'honors',
    q:'How do buffer strips and wetlands along a shore help a lake?',
    choices:['Plants and soil trap nutrient-rich runoff before it reaches the water','They add oxygen directly','They kill algae','They warm the water'],correct:0,
    steps:['Runoff slows down as it passes through vegetation.','Plants take up nitrogen and phosphorus; soil traps sediment.','Less nutrient in, smaller blooms.'],
    lab:{set:{runoff:100,buffer:true},look:'Compare the bloom with and without buffers.'}},
  {id:'limiting',kind:'test',lvl:'honors',
    q:'In most freshwater lakes, adding which nutrient causes the biggest bloom?',
    choices:['Phosphorus','Nitrogen','Oxygen','Carbon dioxide'],correct:0,
    steps:['Algae need both N and P.','In fresh water, phosphorus usually runs out first: it is the limiting nutrient.','That is why many states banned phosphate in laundry detergent.'],
    lab:{set:{runoff:100,nut:'P'},look:'Read <b>Limiting nutrient</b>.'}},
  {id:'gulf',kind:'ap',lvl:'ap',
    q:'Each summer a dead zone of several thousand square miles forms in the Gulf of Mexico. What is the main source of its nutrients?',
    choices:['Farm fertilizer carried down the Mississippi River','Oil spills','Ocean currents','Hurricanes'],correct:0,
    steps:['The Mississippi drains farmland across 31 states.','Its nitrate and phosphate feed huge blooms in the Gulf.','Decomposition strips oxygen from the bottom water, and stratification keeps it from mixing back in.'],
    lab:{set:{runoff:60,strat:true},look:'Compare <b>Bottom oxygen</b> with and without stratification.'}}
  ]},
ld50:{
  apNote:'Released questions from College Board. Toxicology questions read dose–response curves and define LD50.',
  ap:[{title:'AP Environmental Science past exam questions',url:'https://apcentral.collegeboard.org/courses/ap-environmental-science/exam/past-exam-questions',note:'Released free-response questions with scoring guidelines.'}],
  questions:[
  {id:'define',kind:'test',lvl:'bio',
    q:'What does LD50 mean?',
    choices:['The dose that kills (or, here, stops) 50% of the test organisms','The safe dose','The dose that harms 1%','The highest dose tested'],correct:0,
    steps:['LD stands for lethal dose.','LD50 is the dose where half the test population is killed.','In this lab, it is the salt level where half as many seeds sprout as in the control.'],
    lab:{set:{n:'50'},look:'Read <b>LD50 estimate</b>.'}},
  {id:'roadsalt',kind:'real',lvl:'bio',
    q:'Lawns along salted roads often have brown strips in spring. How does this lab explain that?',
    choices:['Salt washed off the road reaches doses that stop seeds and roots from growing','Cold kills the grass','Cars drive on it','Snow is toxic'],correct:0,
    steps:['Salt pulls water out of seeds and roots by osmosis.','Near the road, runoff builds up high salt concentrations in the soil.','Plants there sprout and grow poorly, just like the high-salt dishes.'],
    lab:{set:{n:'50',salt:'mgcl'},look:'Compare sprouting in the high-salt dishes.'}},
  {id:'control',kind:'test',lvl:'bio',
    q:'Why does the lab include a dish with no salt?',
    choices:['It is the control: it shows how many seeds sprout when salt isn’t a factor','To save salt','It isn’t needed','To test the water'],correct:0,
    steps:['Not every seed sprouts even in ideal conditions.','The control shows the normal sprout rate.','Each salt dish is compared with that, so you can see the effect of salt alone.']},
  {id:'compare',kind:'test',lvl:'honors',
    q:'Chemical A has an LD50 of 50 mg/kg; chemical B, 5000 mg/kg. Which is more toxic?',
    choices:['A','B','The same'],correct:0,
    steps:['A lower LD50 means less is needed to kill half the population.','A kills half at 1/100 the dose of B.','So A is about 100 times more acutely toxic.']},
  {id:'chronic',kind:'ap',lvl:'ap',
    q:'Why are LD50 tests not enough to set safe limits for drinking water?',
    choices:['They measure short-term (acute) toxicity, not harm from years of small doses','They are too accurate','They only test plants','They measure chronic toxicity'],correct:0,
    steps:['LD50 tests use a single large dose.','Many chemicals (lead, some pesticides) cause harm slowly at low doses.','Regulators use chronic studies, the NOAEL and safety factors (often 100 to 1000×).']}
  ]}
});
